package de.ostms.lc.email.api;import de.ostms.lc.email.domain.EmailDelivery;import java.time.LocalDateTime;import java.util.*;public record EmailDeliveryView(UUID id,UUID lcId,List<String> recipients,String subject,List<String> attachmentNames,String status,String errorMessage,String sentBy,LocalDateTime sentAt){public static EmailDeliveryView from(EmailDelivery e){return new EmailDeliveryView(e.getId(),e.getLetterOfCredit().getId(),split(e.getRecipients()),e.getSubject(),split(e.getAttachmentNames()),e.getStatus(),e.getErrorMessage(),e.getSentBy(),e.getSentAt());}private static List<String> split(String value){return value==null||value.isBlank()?List.of():Arrays.stream(value.split("\\n")).filter(v->!v.isBlank()).toList();}}
